import pandas as pd
import numpy as np

def calculate_indicators(data):
    # Calculate Money Flow Index (MFI)
    data['MFI'] = calculate_mfi(data)

    # Calculate Stochastic
    data['slow_k'], data['slow_d'] = calculate_stochastic(data)

    return data

def calculate_mfi(data):
    # Calculate Money Flow Index (MFI)
    data['typical_price'] = (data['high'] + data['low'] + data['close']) / 3
    data['money_flow'] = data['typical_price'] * data['volume']

    data['positive_flow'] = 0
    data['negative_flow'] = 0

    for i in range(1, len(data)):
        if data['typical_price'].iloc[i] > data['typical_price'].iloc[i-1]:
            data['positive_flow'].iloc[i] = data['money_flow'].iloc[i]
        else:
            data['negative_flow'].iloc[i] = data['money_flow'].iloc[i]

    data['positive_flow'] = data['positive_flow'].rolling(window=14).sum()
    data['negative_flow'] = data['negative_flow'].rolling(window=14).sum()

    data['MFI'] = 100 - (100 / (1 + data['positive_flow'] / data['negative_flow']))

    return data['MFI']

def calculate_stochastic(data):
    # Calculate Stochastic
    data['low14'] = data['low'].rolling(window=14).min()
    data['high14'] = data['high'].rolling(window=14).max()

    data['slow_k'] = ((data['close'] - data['low14']) / (data['high14'] - data['low14'])) * 100
    data['slow_d'] = data['slow_k'].rolling(window=3).mean()

    return data['slow_k'], data['slow_d']

def trading_strategy(data):
    # Initialize variables
    data['position'] = 0
    data['stop_loss'] = 0
    data['take_profit'] = 0

    for i in range(1, len(data)):
        # Check entry rules
        if (data['MFI'].iloc[i] < 20) and (data['slow_k'].iloc[i] < data['slow_d'].iloc[i]):
            data['position'].iloc[i] = 1
            data['stop_loss'].iloc[i] = data['low'].iloc[i] * 0.95
            data['take_profit'].iloc[i] = data['high'].iloc[i] * 1.05
        elif (data['MFI'].iloc[i] > 80) and (data['slow_k'].iloc[i] > data['slow_d'].iloc[i]):
            data['position'].iloc[i] = -1
            data['stop_loss'].iloc[i] = data['high'].iloc[i] * 1.05
            data['take_profit'].iloc[i] = data['low'].iloc[i] * 0.95

        # Check exit rules
        if data['position'].iloc[i] == 1 and ((data['MFI'].iloc[i] > 80) or (data['slow_k'].iloc[i] > data['slow_d'].iloc[i])):
            data['position'].iloc[i] = 0
        elif data['position'].iloc[i] == -1 and ((data['MFI'].iloc[i] < 20) or (data['slow_k'].iloc[i] < data['slow_d'].iloc[i])):
            data['position'].iloc[i] = 0

        # Update stop-loss
        if data['position'].iloc[i] == 1 and data['high'].iloc[i] > data['stop_loss'].iloc[i]:
            data['stop_loss'].iloc[i] = data['high'].iloc[i] * 0.95
        elif data['position'].iloc[i] == -1 and data['low'].iloc[i] < data['stop_loss'].iloc[i]:
            data['stop_loss'].iloc[i] = data['low'].iloc[i] * 1.05

        # Check stop-loss
        if data['position'].iloc[i] == 1 and data['low'].iloc[i] < data['stop_loss'].iloc[i]:
            data['position'].iloc[i] = 0
        elif data['position'].iloc[i] == -1 and data['high'].iloc[i] > data['stop_loss'].iloc[i]:
            data['position'].iloc[i] = 0

    return data

# Example usage
